86	  while (i < line.length) {
87	    if (state.inBlockComment) {
88	      const end = line.indexOf('*/', i);
89	      if (end === -1) return result;
90	      i = end + 2;
91	      state.inBlockComment = false;
92	      continue;
93	    }
94	    if (line[i] === '/' && line[i + 1] === '/' && line[i - 1] !== ':') break;
95	    if (line[i] === '/' && line[i + 1] === '*') {
96	      state.inBlockComment = true;
97	      i += 2;
98	      continue;
99	    }
100	    result += line[i];
101	    i += 1;
102	  }
103	  return result;
104	}
105	
106	function scanFile(filePath) {
107	  const relPath = relative(ROOT, filePath);
108	  const lines = readFileSync(filePath, 'utf8').split('\n');
109	  const state = { inBlockComment: false };
110	  const findings = [];
111	
112	  lines.forEach((rawLine, idx) => {
113	    const lineNo = idx + 1;
